267.sql:
SELECT `bond_type` 
FROM bond 
WHERE `molecule_id` BETWEEN 'TR000' AND 'TR050';

291.sql:
SELECT COUNT(*) AS answer
FROM molecule
WHERE label = '+';

387.sql:
SELECT `name`, `colorIdentity`
FROM cards
WHERE `setCode` = 'OGW' AND `colorIdentity` IS NOT NULL;

419.sql:
SELECT COUNT(*) AS answer
FROM cards
WHERE `borderColor` = 'borderless' AND `edhrecRank` > 12000;

625.sql:
SELECT COUNT(*) AS answer
FROM users
WHERE Location = 'New York, NY';

653.sql:
SELECT OwnerDisplayName
FROM posts
WHERE ViewCount = (SELECT MAX(ViewCount) FROM posts);

882.sql:
SELECT MIN(year) AS answer
FROM races
WHERE name = 'Singapore Grand Prix';

1035.sql:
SELECT DISTINCT `team_fifa_api_id`
FROM Team_Attributes
WHERE `buildUpPlaySpeed` > 50 AND `buildUpPlaySpeed` < 60;

1393.sql:
SELECT first_name, last_name, email
FROM member
WHERE position = 'Secretary';
